#!/usr/bin/env python3
"""Select an original minigame through its native module lifecycle in isolated QA."""
import os
import json,pathlib,urllib.request,urllib.error,sys
names=['BarfORamaMiniGame','PieEatingMinigame','AsleepOnJobMinigame','RatsInTheKitchenMinigame','KnifeSharpeningMinigame','KitchenFireMinigame','PratfallPickupMinigame','EndlessBuffetMinigame','CleanupMinigame','KnifeSkillsMinigame','PepperChopMinigame']
name=sys.argv[1];assert name in names or name=='stop'
source='''(async()=>{const o=orderup,r=o.runtime;await o.controller.pause();r.resumeClock();try{const manager=r.u32(r.elf.address('_ZN3Mdl9g_ManagerE')),code=await r.call('_ZN3Mdl11MinigameMod7GetNameEv'),mod=await r.call('_ZN3Mdl7Manager9GetModuleE10checksum32',[manager,code]);const name=__NAME__,running=await r.call('_ZN3Mdl6Module7RunningEv',[mod]);if(name==='stop'){if(running)await r.call('_ZN3Mdl7Manager10StopModuleE10checksum32',[manager,code]);return{stopped:true,mod};}if(running)throw Error('Finish the active minigame through its original UI before starting another');if(name==='PepperChopMinigame'||name==='KnifeSkillsMinigame'){const marketCode=await r.call('_ZN3Mdl14MarketDistrict7GetNameEv'),market=await r.call('_ZN3Mdl7Manager9GetModuleE10checksum32',[manager,marketCode]);await r.call(name==='PepperChopMinigame'?'_ZN3Mdl14MarketDistrict16SelectPepperChopEv':'_ZN3Mdl14MarketDistrict17SelectKnifeSkillsEv',[market]);return{name,market,original_market_selection:true};}const child=r.u32(r.elf.address('_ZN'+name.length+name+'9g_ManagerE'));if(!child)throw Error('Minigame manager not initialized');const vtable=r.u32(child),key=await r.call(r.u32(vtable+0x28),[child]);await r.call('_ZN3Mdl11MinigameMod11SetMinigameE10checksum32',[mod,key]);if(r.u32(mod+0x1c)!==child)throw Error('Native game selection did not match');if(name==='AsleepOnJobMinigame')await r.call('_ZN19AsleepOnJobMinigame7Manager21SetAssistantChefIndexEi',[child,0]);await r.call('_ZN3Mdl7Manager11StartModuleE10checksum32',[manager,code]);return{name,child,key,mod,running:await r.call('_ZN3Mdl6Module7RunningEv',[mod])};}finally{r.pauseClock();}})()'''.replace('__NAME__',json.dumps(name))
record=json.loads(pathlib.Path(os.environ.get('OU_CONTROL_RECORD','analysis/performance-control.json')).read_text());req=urllib.request.Request(record['control_url'],data=json.dumps({'action':'eval','source':source}).encode(),headers={'Content-Type':'application/json'})
try:
 with urllib.request.urlopen(req,timeout=660) as r:print(json.dumps(json.load(r),indent=2))
except urllib.error.HTTPError as e:print(e.read().decode());sys.exit(1)
